const items = $input.all().map(i => i.json).filter(r => r && r.categoria);

if (items.length === 0) {
  return [{
    json: {
      encontradas: 0,
      categorias: [],
      mensaje: 'No hay categorías con productos disponibles en este momento.'
    }
  }];
}

return [{
  json: {
    encontradas: items.length,
    categorias: items.map(c => ({
      categoria: c.categoria,
      total_productos: c.total_productos,
      precio_desde: parseFloat(c.precio_desde),
      precio_hasta: parseFloat(c.precio_hasta)
    }))
  }
}];
